def check_m_possible(m, n=200):
    # We need to find k, l such that
    # 1) k <= n-1
    # 2) l <= k+1
    # 3) m <= l
    # 4) 2*m + (k-1)*(k-2)//2 <= n*k - l*(l-1)//2
    for k in range(1, n):
        for l in range(1, n + 1):
            if l <= k + 1 and m <= l:
                N_min = 2*m + (k-1)*(k-2)//2
                N_max = n*k - l*(l-1)//2
                if N_min <= N_max:
                    return True, k, l
    return False, None, None

for m in range(200, 190, -1):
    possible, k, l = check_m_possible(m)
    if possible:
        print(f"m={m} is possible with k={k}, l={l}")
        break
    else:
        print(f"m={m} is not possible")

