def solve_v4():
    n = 200
    max_m = 0
    for k in range(1, n + 1):
        for l in range(1, n + 1):
            if l <= k + 1:
                # What is the largest m we can get?
                # Condition: m <= l.
                # Condition: N_min(m, k) <= N_max(k, l)
                # N_min(m, k) = 2*m + (k-2)*(k-1)//2 if m > k-2 else m + k*(k-1)//2
                # N_max(k, l) = n*k - l*(l-1)//2 if l <= k else (n-l)*k + k*(k+1)//2

                # We want to find the largest m <= l such that N_min(m, k) <= N_max(k, l).
                # Let's test all m from 1 to l.
                for m in range(1, l + 1):
                    if m > k - 2:
                        N_min = 2*m + (k-2)*(k-1)//2
                    else:
                        N_min = m + k*(k-1)//2

                    if l <= k:
                        N_max = n*k - l*(l-1)//2
                    else:
                        N_max = (n-l)*k + k*(k+1)//2

                    if N_min <= N_max:
                        if m > max_m:
                            max_m = m
    return max_m

print(solve_v4())
